"""Beginner explanations for retval storage and string wrapper control flow."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1773': ('돌려줄 물건의 검사 결과를 담는 칸이 있어요. 작은 칸들이 줄지어 있다고 해서 언제나 한 칸씩만 읽고 쓰는 것은 아니에요.', '반환값 검사 정보의 저장 크기와 선언을 함께 읽습니다.', 'shadow 저장 공간은 8칸, origin 저장 공간은 4칸으로 그려 보세요. 한 칸은 1바이트라고 적으세요.', ['set_retval_metadata는 함수가 돌려줄 값의 검사 정보를 저장해요. retval은 반환값이라는 뜻이에요. shadow는 준비 상태를 나타내고 origin은 관련 원인 기록 번호예요. 실제로 돌려줄 포인터 값과 그 검사 정보는 별개의 값이에요.', '먼저 kmsan_get_context로 현재 검사 문맥을 얻어요. 문맥은 현재 작업에서 사용할 검사 상태들을 모아 놓은 구조예요. ctx->cstate는 그 안의 컴파일러용 상태 묶음에 접근하는 표현식이에요.', '*(u64 *)(ctx->cstate.retval_tls) = shadow는 반환값용 공간의 시작을 u64를 저장할 주소로 해석하고 shadow를 써요. u64는 64비트예요. 8비트가 1바이트이므로 여기서 쓰는 크기는 8바이트예요.', 'retval_tls가 char 배열로 선언됐어도 이 식은 char 한 칸에만 쓰는 대입이 아니에요. 앞의 u64 포인터 형식 변환과 별표를 함께 읽어야 해요. 별표는 해당 주소가 가리키는 저장 장소를 사용한다는 뜻이에요.', 'origin은 ctx->cstate.retval_origin_tls에 저장해요. 실제 선언에서 이 필드는 u32라서 32비트, 즉 4바이트예요. 첫 인자의 원인 공간인 param_origin_tls라는 char 배열과는 저장 형태가 달라요.', '앞의 getter가 첫 char만 읽었다면 이 setter가 u32로 저장한다고 빠진 세 바이트를 되찾지는 못해요. 받은 숫자를 지정된 크기로 저장할 뿐이에요. 이러한 주소 형식 변환은 이 커널의 저장 규약을 전제로 하므로 아무 작은 배열에 8바이트를 써도 된다는 뜻은 아니에요.'], [('retval_tls 시작에 shadow를 쓰는 식은 몇 비트 값을 저장하나요?', ['char 한 칸인 8비트만 저장해요', 'u64인 64비트를 저장해요'], '정답은 두 번째예요. u64 포인터로 바꾼 뒤 역참조해 대입해요. 64 ÷ 8 = 8바이트이며 배열의 원래 요소 이름만 보고 1바이트라고 판단하면 안 돼요.'), ('retval_origin_tls도 param_origin_tls처럼 char 배열인가요?', ['아니요. 별도 u32 필드예요', '네. 이름만 다르고 같은 char 배열이에요'], '정답은 첫 번째예요. 원문 선언은 반환 원인 필드를 u32로 두어요. 비슷한 이름이어도 타입을 각각 확인해야 해요.')]), 'os1774': ('공책 내용을 복사하는 일과 그 내용의 검사표를 옮기는 일이 차례로 있어요. 검사 도구를 껐다고 공책 복사 자체가 사라지는 것은 아니에요.', '실제 복사와 검사 정보 복사의 순서 및 겹침 조건을 이해합니다.', '서로 다른 두 버퍼를 그리고 데이터 복사 화살표와 검사 정보 이동 화살표를 따로 그리세요.', ['__msan_memcpy는 실제 memcpy를 감싸 검사 작업을 덧붙인 함수예요. dst는 도착 주소, src는 원본 주소, n은 바이트 수예요. 예를 들어 별개 버퍼의 ABC를 세 바이트 복사하면 도착 버퍼에도 ABC가 생겨요.', '먼저 첫 인자인 dst 포인터 자체의 검사 정보를 저장해요. 그다음 result = __memcpy(dst, src, n)으로 실제 데이터를 복사해요. result는 복사 결과로 돌려줄 도착 주소예요.', '실제 복사 호출 뒤에 n이 0인지, KMSAN이 꺼졌는지, 도구 자신의 처리 중인지 확인해요. 해당 조건에서 돌아가더라도 앞의 실제 복사 호출을 취소하는 것은 아니에요. 검사 도구 설정이 프로그램의 원래 복사 일을 없애면 안 되기 때문이에요.', '검사도 진행하는 경로라면 enter_runtime으로 들어가 kmsan_internal_memmove_metadata를 호출하고 leave_runtime으로 나와요. 이 도우미는 복사된 데이터에 맞춰 검사 정보를 옮기는 일을 맡아요. 실제 데이터 복사와 대상 공간이 달라요.', '이름에 memmove가 들어간 검사 도우미를 쓴다고 실제 __memcpy가 memmove로 바뀌지는 않아요. 데이터 memcpy에는 원본과 도착 범위가 겹치지 않아야 한다는 조건이 있어요. 같은 버퍼 안에서 겹치는 이동은 해당 조건에 맞는 memmove로 생각해야 해요.', '마지막에는 저장해 둔 dst 포인터의 검사 정보를 반환값용 공간에 넣고 result를 반환해요. 이는 끝까지 내려온 경로의 순서예요. 앞에서 돌아간 경로는 검사 정보 이동과 이 마지막 설정을 건너뛰므로 두 경로를 따로 그려 보세요.'], [('검사 정보에 memmove 도우미를 쓰면 실제 memcpy의 겹치는 범위도 허용되나요?', ['네. 검사 도우미 이름이 실제 복사의 조건을 바꿔요', '아니요. 실제 데이터 memcpy의 조건은 그대로예요'], '정답은 두 번째예요. 실제 데이터는 __memcpy가 처리하고 검사 정보는 다른 함수가 처리해요. 뒤 함수의 이름으로 앞 함수의 겹침 조건을 바꿀 수는 없어요.'), ('유효하고 겹치지 않는 범위에서 KMSAN이 꺼져 있어도 실제 복사 호출은 하나요?', ['네. 활성 여부 검사보다 먼저 호출해요', '아니요. 데이터 복사까지 모두 생략해요'], '정답은 첫 번째예요. __memcpy 호출이 조건문 앞에 있어요. 이후의 반환은 추가 검사 작업을 생략하는 것이에요.')]), 'os1775': ('한 줄의 글자를 오른쪽으로 옮길 때, 방금 덮어쓴 글자를 다시 읽으면 원래 내용이 사라질 수 있어요. memmove는 겹치는 이동에서도 원래 내용을 옮기는 효과를 보장해요.', '겹치는 데이터 이동과 그 뒤 검사 정보 처리의 차이를 이해합니다.', 'ABCDE 다섯 칸을 그리고 첫 네 칸 ABCD를 오른쪽 한 칸으로 옮긴 결과 AABCD를 적어 보세요.', ['memmove는 원본 범위와 도착 범위가 겹쳐도 사용할 수 있는 메모리 이동 함수예요. 필요한 원본 내용을 먼저 보관했다가 옮기는 것과 같은 결과를 내야 해요. 실제 구현이 언제나 별도의 큰 임시 배열을 만든다는 뜻은 아니에요.', '예를 들어 ABCDE에서 첫 네 글자 ABCD를 한 칸 오른쪽으로 옮기면 AABCD가 돼요. 앞에서부터 무작정 덮어쓰며 방금 쓴 글자를 원본으로 다시 읽으면 AAAAA가 될 수 있어요. 겹침을 고려하는 이유가 여기에 있어요.', '__msan_memmove는 먼저 dst 포인터의 검사 정보를 받아 두고 실제 __memmove를 호출해요. 실제 이동이 끝난 뒤 n이 0인지, 검사가 꺼졌는지, 도구 자신의 처리 중인지 살펴요.', '도구 처리 중이어서 돌아가는 경우에도 앞의 실제 데이터 이동은 이미 실행됐어요. 다만 뒤의 검사 정보 이동 호출과 반환값용 검사 정보 설정은 생략해요. 데이터 작업과 추가 추적 작업을 별도 줄로 표시해 보세요.', '계속 진행하는 경로는 enter_runtime → 검사 정보 이동 → leave_runtime 순서예요. 이어 반환값 검사 정보를 설정하고 실제 이동 함수가 준 결과를 반환해요. 검사 정보 이동은 데이터가 준비됐는지와 관련 원인을 함께 따라가게 하는 작업이에요.', '종이에 글자를 옮겨 보는 활동이나 도우미를 직접 호출하는 모델 실습은 전체 커널의 자동 검사 실행과 달라요. 컴파일러가 실제로 검사 코드를 끼워 넣은 커널을 실행했다는 증거가 되지는 않아요. 이 수업에서는 원문 순서와 이동 결과 예시를 구별해 이해하세요.'], [('runtime 상태가 1이라 뒤의 검사를 생략해도 실제 memmove 호출은 실행하나요?', ['아니요. 데이터 이동 전부터 무조건 끝나요', '네. 그 조건을 보기 전에 실제 이동을 호출해요'], '정답은 두 번째예요. result = __memmove가 조건문보다 앞에 있어요. 추가 검사 생략과 실제 이동 생략은 서로 다른 뜻이에요.'), ('도우미를 직접 부르는 모델 실습만으로 컴파일러가 검사 코드를 넣은 전체 커널을 실행했다고 할 수 있나요?', ['아니요. 직접 호출한 모델과 전체 계측 커널 실행은 달라요', '네. 함수 하나를 부르면 모든 커널 명령의 검사가 증명돼요'], '정답은 첫 번째예요. 모델은 선택한 함수와 조건을 살피는 활동이에요. 컴파일러가 끼워 넣은 코드와 실제 커널 전체의 실행까지 자동으로 검증되지는 않아요.')]), 'os1776': ('옮길 물건이 0개여도 작업표를 갱신하는지는 절차마다 달라요. 비슷한 이름의 함수라도 돌아가는 위치가 같은지 살펴봐야 해요.', '길이 0에서 복사 함수와 채우기 함수의 반환 경로를 비교합니다.', '세 줄에 memcpy, memmove, memset을 쓰고 n=0일 때 setter에 도달하는지 표시하세요. 검사는 켜짐, runtime 밖으로 가정하세요.', ['n은 처리할 바이트 수예요. n이 0이면 이 요청으로 옮기거나 채울 데이터 바이트가 없어요. 여기서는 올바른 호출 조건을 갖춘 경우를 비교해요. 길이가 0이라는 이유만으로 임의의 잘못된 포인터 사용이 허용된다고 일반화하지 마세요.', 'memcpy와 memmove 도우미는 먼저 첫 인자의 검사 정보를 읽고 실제 데이터 함수를 호출해요. 그 뒤 if (!n) return result가 있어요. !n은 n이 0일 때 참이 되는 조건이에요.', '이 지점에서 돌아가면 아래 검사 정보 이동과 set_retval_metadata를 실행하지 않아요. 즉 이 wrapper는 반환값 검사 정보를 새로 써 주지 않아요. 이미 들어 있던 값을 반드시 0으로 지운다는 코드도 없어요.', '반면 __msan_memset에는 같은 if (!n) 분기가 없어요. 실제 채우기 함수를 부른 뒤 활성 여부와 runtime 여부를 확인해요. KMSAN이 켜져 있고 runtime 밖이면 n이 0이어도 뒤로 계속 가요.', '그 경로는 unpoison 도우미에 길이 0을 전달하고 반환값 검사 정보도 설정해요. 호출했다는 사실과 데이터 바이트가 바뀌었다는 사실은 달라요. 여기서 길이는 여전히 0이므로 한 바이트를 새로 채운다고 해석하면 안 돼요.', '예시로 반환값 검사 공간에 기존 표시 99가 있고 첫 인자 표시가 7이라고 해 봐요. 다른 동작이 그 공간을 바꾸지 않는 모델에서는 길이 0 복사 경로는 99를 남기고, 활성 정상 memset 경로는 setter로 7을 써요. 이는 분기 비교 예시이며 모든 컴파일러 호출 상황의 상태를 보장하는 숫자는 아니에요.'], [('길이 0인 memcpy·memmove가 if (!n)에서 돌아가면 반환값 검사 정보 setter를 호출하나요?', ['네. 돌아간 뒤에도 아래 setter를 실행해요', '아니요. 그 반환 경로는 setter를 건너뛰어요'], '정답은 두 번째예요. return은 함수 실행을 끝내요. 따라서 그 아래 setter로 새 값을 쓰지 않으며 자동으로 0을 쓴다는 뜻도 아니에요.'), ('memset 도우미에도 같은 위치의 길이 0 조기 반환이 있나요?', ['아니요. 검사가 켜지고 runtime 밖이면 길이 0의 도우미 호출과 setter까지 가요', '네. 세 함수의 모든 조건문이 같아요'], '정답은 첫 번째예요. 원문의 memset에는 if (!n)이 없어요. 비슷한 함수라도 본문의 조건과 순서를 각각 비교해야 해요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_439.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
